// ../../packages/diagrams/src/kinds/xychart/vocabulary.ts
function xychartVocabulary() {
  return {
    statements: [
      {
        syntax: 'xychart "<title>" direction=<vertical|horizontal> stack=<on|off> values=<on|off> desc="<text>"',
        meaning: "The header; every option is optional. horizontal puts the places down the side, which suits a ranking. stack=on stacks the bar series. values=off leaves the numbers off the bars. The title is in a corner tab.",
        example: 'xychart "Latency by week" stack=off'
      },
      {
        syntax: 'x "<title>" ["<place>" "<place>"]  or  x "<title>" <from> to <to>',
        meaning: "The horizontal axis, once: named places in square brackets, or a number range that every series is spread evenly over. Each series then has one value for each place. Write a negative number as -5, and text with + ( < # or a bare / in quotes.",
        example: 'x "Week" ["W1" "W2" "W3" "W4"]'
      },
      {
        syntax: 'y "<title>" unit=<text> min=<number> max=<number>',
        meaning: 'The value axis, once; every part is optional. Ticks are on round numbers. Bars and areas start at zero unless min= says otherwise (lint warns). A word unit such as "ms" goes in the title, a symbol such as "$" or "%" on the numbers.',
        example: 'y "Latency" unit="ms" min=0 max=800'
      },
      {
        syntax: 'bar|line|area "<name>" [<number> <number>] tone=<tone> icon=<set:name>',
        meaning: `One series: its name, then one plain number for each place in square brackets. area adds a wash under its line. Series take ${joinWords([...SERIES_TONES2], "and")} in turn; tone= chooses one. Up to ${XYCHART_LINT.maxDirectLabels} series are named beside their last points, more in a legend.`,
        example: 'line "p95" [310 360 345 420]'
      },
      {
        syntax: 'threshold "<label>" <number> tone=<tone> breach=<above|below|none>',
        meaning: `A labelled reference line, ${THRESHOLD_TONE} unless tone= says otherwise. A bar or point on the wrong side of it (above by default) is drawn in its tone. The axis grows to hold it.`,
        example: 'threshold "SLO 400 ms" 400 tone=red'
      },
      {
        syntax: 'note "<text>" at="<place>"',
        meaning: "A callout above the plot with a dotted line down to a place on the x axis (an x value on a number axis). Not on a horizontal chart.",
        example: 'note "Release 2.3" at="W3"'
      },
      {
        syntax: 'desc "<text>"',
        meaning: "The plain-language description, for assistive technology; the same as desc= on the header.",
        example: 'desc "How the latency of the API moved over eight weeks."'
      }
    ],
    limits: [
      { name: "series", value: XYCHART_LINT.maxSeries, meaning: `More than this draws a warning: the colours stop being easy to tell apart. More than ${XYCHART_LIMITS.maxSeries} is refused with E140.` },
      { name: "places", value: XYCHART_LIMITS.maxPoints, meaning: "Places on the x axis; more is refused with E140. The labels of a crowded axis are thinned, with a warning." }
    ]
  };
}

